-- ========================================================

function DebugBoxMoveButton:__init( debugBox_, moveButton_ )

    self.debugBox = debugBox_ -- DebugBox
    self.moveButton = moveButton_ -- Button
    self.moveBtnImage =  KTool.GetComponent(self.moveButton.gameObject, typeof(Image))
    assert(self.moveBtnImage)

    self.moveButton.onClick:AddListener(function()
        self:OnPress()
    end)

    self.onOff = OnOff.Off
    self:Set(self.onOff)
end


function DebugBoxMoveButton:__delete()
end



-- =========================================== Self ================================================ --


function DebugBoxMoveButton:isOpen()
    return self.onOff == "On"
end


-- Allow external triggers to simulate a button press
function DebugBoxMoveButton:OnPress()
    self.onOff = (self.onOff == OnOff.On) and OnOff.Off or OnOff.On -- swap
    self:Set(self.onOff)
end


function DebugBoxMoveButton:Set(state_)
    if state_ == OnOff.On then
        -- Enable functionality
        -- Physics.autoSimulation = false
        self.debugBox.humanMotor.Capsule.enabled = false
        self.debugBox.catMotor.Capsule.enabled = false

        self.debugBox.humanMotor.enabled = false
        self.debugBox.catMotor.enabled = false

        self.moveBtnImage.color = Color.green
        KTool.SetActive( self.debugBox.movePanel.gameObject, true )
    else
        -- Disable functionality
        -- Physics.autoSimulation = true
        self.debugBox.humanMotor.Capsule.enabled = true
        self.debugBox.catMotor.Capsule.enabled = true

        self.debugBox.humanMotor.enabled = true
        self.debugBox.catMotor.enabled = true

        self.moveBtnImage.color = Color.white
        KTool.SetActive( self.debugBox.movePanel.gameObject, false )
    end
end











return DebugBoxMoveButton

